-- 0001_roles.sql: PostgreSQL-only least-privilege role separation (ADR-0005, ADR-0007 DES-010, #38)
-- Executed by operator / database provisioning identity before schema migrations.
--
-- SECURITY: no password is embedded here. Pass one per login role via psql variables, generated by you
-- (e.g. `openssl rand -base64 32`) and stored only in your secret store / the server .env:
--   psql -v ON_ERROR_STOP=1 -d <db> \
--        -v app_password="$APP_PW" -v resolver_password="$RESOLVER_PW" \
--        -v migrator_password="$MIGRATOR_PW" -v backup_password="$BACKUP_PW" -f 0001_roles.sql
-- If a variable is missing psql aborts (fail closed) and the roles stay without a usable password.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'awshortlink_owner') THEN
        CREATE ROLE awshortlink_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'awshortlink_migrator') THEN
        CREATE ROLE awshortlink_migrator LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
    END IF;
    GRANT awshortlink_owner TO awshortlink_migrator;

    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'awshortlink_app') THEN
        CREATE ROLE awshortlink_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'awshortlink_resolver') THEN
        CREATE ROLE awshortlink_resolver LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'awshortlink_backup') THEN
        CREATE ROLE awshortlink_backup LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE BYPASSRLS;
    END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS shortlink AUTHORIZATION awshortlink_owner;

REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA shortlink TO awshortlink_app, awshortlink_resolver, awshortlink_backup, awshortlink_migrator;

ALTER ROLE awshortlink_app SET search_path = shortlink;
ALTER ROLE awshortlink_resolver SET search_path = shortlink;
ALTER ROLE awshortlink_migrator SET search_path = shortlink;
ALTER ROLE awshortlink_backup SET search_path = shortlink;

-- Passwords (psql variables are not expanded inside the DO block above, so they are applied here).
ALTER ROLE awshortlink_migrator PASSWORD :'migrator_password';
ALTER ROLE awshortlink_app PASSWORD :'app_password';
ALTER ROLE awshortlink_resolver PASSWORD :'resolver_password';
ALTER ROLE awshortlink_backup PASSWORD :'backup_password';
